    for (row, owner) in rows.iter().zip(owners) {
        assert_eq!(row["path"], owner);
    }
    let row = rows.iter().find(|r| r["path"] == path).unwrap();
    let mut before = if path == "src/cleanup_plan/replay/path_join/shared_insertions_tests.rs" {
