                        result.as_ref().err(),
                        Some(&legacy),
                        "complete driver keeps every diagnostic field"
                    );
                    drop(result);
                    drop(budget);
                    drop(opted);
                    let receipt = scope.finish();
                    assert!(
                        receipt.first_refusal.is_none() && receipt.first_work_refusal.is_none()
