        let mut exact = ReplayBudget::with_physical(function, used).unwrap();
        check_exits(function, &mut exact).unwrap();
        assert_eq!(exact.physical.as_deref().unwrap().charged(), used);
        let mut short = ReplayBudget::with_physical(function, used - 1).unwrap();
        assert!(check_exits(function, &mut short).is_err());

        let continue_id = function
            .cleanup_plan
            .lexical_control
            .as_ref()
            .unwrap()
            .exits
            .iter()
            .find(|exit| exit.kind == LexicalExitKind::Continue)
            .expect("authored iterator continue")
            .exit;
        let mut forged = function.clone();
        let exit = &mut forged.cleanup_plan.exits[continue_id.0 as usize];
        assert_eq!(
            expected_exit_regions(function, exit).unwrap(),
            exit.leaves_regions
        );
        let last = exit.leaves_regions.last().expect("continue leaves scratch");
        let retained = function.cleanup_plan.regions[last.0 as usize]
            .parent
            .unwrap();
        exit.leaves_regions.push(retained);
        let mut budget = ReplayBudget::with_physical(&forged, usize::MAX).unwrap();
        let error = check_exits(&forged, &mut budget).unwrap_err();
        assert!(detailed(&forged, error)
            .message
            .contains("exact source-to-target region chain"));

        let mut forged = function.clone();
        let action = forged
            .cleanup_plan
            .exits
            .iter_mut()
            .flat_map(|exit| &mut exit.finalize_in_order)
            .find(|action| action.active_case.is_some())
            .expect("case-qualified iterator finalizer");
        action.active_case = None;
        let mut budget = ReplayBudget::with_physical(&forged, usize::MAX).unwrap();
        let error = check_exits(&forged, &mut budget).unwrap_err();
        assert!(detailed(&forged, error)
            .message
            .contains("exact variant case path"));

        let mut forged = function.clone();
        let flag = forged
            .cleanup
            .flags
            .iter_mut()
            .find(|flag| flag.place.projections.len() == 2)
            .expect("case-qualified iterator flag");
        flag.place.projections.swap(0, 1);
        let mut budget = ReplayBudget::with_physical(&forged, usize::MAX).unwrap();
        assert!(validate_inventory_coverage(context, &forged, &mut budget).is_err());

        let mut forged = function.clone();
        let slot = forged
            .cleanup_plan
            .slots
            .iter_mut()
            .find(|slot| {
                matches!(
                    slot.storage,
                    crate::cleanup_plan::StorageId::CallArgument { .. }
                ) && crate::iterator_ops::is_iter(&slot.ty)
            })
            .expect("owned iterator argument slot");
        slot.field_liveness_shape = crate::cleanup::FieldLivenessShape::NoDrop;
        let mut budget = ReplayBudget::with_physical(&forged, usize::MAX).unwrap();
        assert!(validate_inventory_coverage(context, &forged, &mut budget).is_err());

        for attack in 0..3 {
            let mut hostile = function.clone();
            let ResolvedExprKind::Block { statements, .. } = &mut hostile.body.kind else {
                panic!("function block");
            };
            let inner = statements
                .iter_mut()
                .find_map(|statement| {
                    let ResolvedStatement::Let { value, .. } = statement else {
                        return None;
                    };
                    let ResolvedExprKind::Block { statements, .. } = &mut value.kind else {
                        return None;
                    };
                    matches!(
                        statements.last(),
                        Some(ResolvedStatement::LexicalWhile { .. })
                    )
                    .then_some(statements)
                })
                .expect("owning wrapper");
            let [ResolvedStatement::Let { value: seed, .. }, ResolvedStatement::LexicalWhile {
                condition, latch, ..
            }] = inner.as_mut_slice()
            else {
                panic!("lowered seed and loop");
            };
            match attack {
                0 => {
                    let LoopLatchKind::OwnedIteratorStep {
                        next, assignment, ..
                    } = latch
                    else {
                        panic!("owned latch");
                    };
                    *next = assignment.clone();
                }
                1 => {
                    let ResolvedExprKind::Call { args, .. } = &mut seed.kind else {
                        panic!("iterator seed");
                    };
                    args[0].ownership = OwnershipMode::Borrow;
                }
                2 => {
                    let ResolvedExprKind::Match { arms, .. } = &mut condition.kind else {
                        panic!("iterator condition");
                    };
                    let crate::hir::ResolvedMatchPattern::Variant { fields, .. } =
                        &mut arms[1].pattern
                    else {
                        panic!("yielded fields");
                    };
                    fields.swap(0, 1);
                }
                _ => unreachable!(),
            }
            let mut budget = ReplayBudget::with_physical(&hostile, usize::MAX).unwrap();
            assert!(selected_profile::paid::validate(context, &hostile, &mut budget).is_err());
        }
    });
}

pub(in crate::cleanup_plan::replay) mod byte_iterator {
    //! Closed preflight for the compiler-lowered Bytes iterator protocol.
    //! Latch and cleanup replay remain independent of these shape checks.
    use crate::hir::{
        OwnershipMode, ResolvedExpr, ResolvedExprKind, ResolvedFunction, ResolvedMatchArm,
        ResolvedMatchMode, ResolvedMatchPattern, ResolvedType,
    };
    use crate::iterator_ops::{self, IteratorOp};

    use super::super::super::selected_context::paid::refusal;
    use super::{Error, ReplayBudget};

    fn nominal(ty: &ResolvedType, id: &str) -> bool {
        matches!(ty, ResolvedType::Nominal { declaration, arguments }
        if declaration.as_str() == id && arguments.as_slice() == [ResolvedType::Bytes])
    }

    pub(in super::super) fn local_type(ty: &ResolvedType) -> bool {
        nominal(ty, iterator_ops::ITER_ID) || nominal(ty, iterator_ops::STEP_ID)
    }

    pub(in crate::cleanup_plan::replay) fn step(ty: &ResolvedType) -> bool {
        nominal(ty, iterator_ops::STEP_ID)
    }

    pub(in super::super) fn done(expression: &ResolvedExpr) -> bool {
        matches!(&expression.kind, ResolvedExprKind::ConstructVariant { variant, case, fields }
        if variant.as_str() == iterator_ops::STEP_ID && case.as_str() == iterator_ops::DONE_ID
            && fields.is_empty() && step(&expression.ty) && expression.ownership == OwnershipMode::Own)
    }

    pub(in crate::cleanup_plan::replay) fn call(
        function: &ResolvedFunction,
        expression: &ResolvedExpr,
        op: IteratorOp,
        budget: &mut ReplayBudget,
    ) -> Result<(), Error> {
        type Controls<'a> = (
            &'a ResolvedFunction,
            &'a ResolvedExpr,
            &'a mut ReplayBudget,
            IteratorOp,
            Option<&'a ResolvedExpr>,
            (&'static str, &'static str),
            Result<(), Error>,
        );
        budget.reserve_array::<Controls<'_>>(function, 2, "selected Bytes iterator call")?;
        budget.charge(function, 8, "selected Bytes iterator call")?;
        let (input, output) = match op {
            IteratorOp::VecIntoIter => (crate::prelude::VEC_ID, iterator_ops::ITER_ID),
            IteratorOp::Next => (iterator_ops::ITER_ID, iterator_ops::STEP_ID),
        };
        if !matches!(&expression.kind, ResolvedExprKind::Call { type_arguments, instance: None, args, .. }
        if type_arguments.as_slice() == [ResolvedType::Bytes]
            && matches!(args.as_slice(), [arg] if nominal(&arg.ty, input) && arg.ownership == OwnershipMode::Own))
            || !nominal(&expression.ty, output)
            || expression.ownership != OwnershipMode::Own
        {
            return Err(refusal(
                function,
                budget,
                "selected Bytes iterator call shape disagrees",
            ));
        }
        Ok(())
    }

    pub(in crate::cleanup_plan::replay) fn arms(
        function: &ResolvedFunction,
        mode: ResolvedMatchMode,
        arms: &[ResolvedMatchArm],
        budget: &mut ReplayBudget,
    ) -> Result<(), Error> {
        type Controls<'a> = (
            &'a ResolvedFunction,
            ResolvedMatchMode,
            &'a [ResolvedMatchArm],
            &'a mut ReplayBudget,
            OwnershipMode,
            [&'a ResolvedMatchArm; 2],
            [&'a ResolvedMatchPattern; 2],
            Result<(), Error>,
        );
        budget.reserve_array::<Controls<'_>>(function, 2, "selected Bytes iterator match")?;
        budget.charge(function, 12, "selected Bytes iterator match")?;
        let ownership = match mode {
            ResolvedMatchMode::Own => OwnershipMode::Own,
            ResolvedMatchMode::Borrow => OwnershipMode::Borrow,
            ResolvedMatchMode::Value => {
                return Err(refusal(
                    function,
                    budget,
                    "selected Bytes iterator match mode disagrees",
                ));
            }
        };
        if !matches!(arms, [done, yielded]
        if done.guard.is_none() && yielded.guard.is_none()
            && matches!(&done.pattern, ResolvedMatchPattern::Variant { variant, case, fields }
                if variant.as_str() == iterator_ops::STEP_ID && case.as_str() == iterator_ops::DONE_ID && fields.is_empty())
            && matches!(&yielded.pattern, ResolvedMatchPattern::Variant { variant, case, fields }
                if variant.as_str() == iterator_ops::STEP_ID && case.as_str() == iterator_ops::YIELD_ID
                    && matches!(fields.as_slice(), [item, rest]
                        if item.field.as_str() == iterator_ops::ITEM_ID
                            && item.binding.ty == ResolvedType::Bytes && item.binding.ownership == ownership
                            && rest.field.as_str() == iterator_ops::REST_ID
                            && nominal(&rest.binding.ty, iterator_ops::ITER_ID) && rest.binding.ownership == ownership)))
        {
            return Err(refusal(
                function,
                budget,
                "selected Bytes iterator cases disagree",
            ));
        }
        Ok(())
    }
}

