// The height-stable directory insertion owns these additional initialized
// controls even for the first node, whose parent is NIL. Duplicates and empty
// directories do not enter that receiver. Preserve the exact, short and zero
// frontiers against its complete physical invoice.
fn insertion_receivers() -> usize {
    2 * std::mem::size_of::<(u8, bool)>()
        + 2 * std::mem::size_of::<(&mut ReplayBudget, &ResolvedFunction, usize, &str)>()
        + 2 * std::mem::size_of::<Result<(), Diagnostic>>()
        + insertion_receivers()
                insertion_receivers() + Directory::<&ExpressionId>::node_layout_bytes()
                Directory::<&ExpressionId>::node_layout_bytes()

    let rebound = restore_observer_visibility(current);
    let current = rebound.as_deref().unwrap_or(current);

// Live lexical receiver controls: every full-caller comparison enters the
// ordinary driver and retains its later certificate/CFG/path/factored checks.
fn live_lexical_program(calls: usize) -> ResolvedProgram {
    let calls = "leaf(n);".repeat(calls);
    let source = format!(
        r#"module replay.live_directories;
@id("live.leaf") fn leaf(n:i64)->i64 {{n}}
@id("live.walk") fn walk()->i64 {{
 let mut n=0;
 while n<4 {{ n=n+1; {calls} if n==1 {{continue;}}; if n==3 {{break;}}; 0 }}
 if n==2 {{return n;}}; return 9;
}}
@id("app.main") fn main()->i64 {{walk()}}
"#
    );
    crate::hir::resolve(&crate::check(&source, "live-directory.spx").unwrap()).unwrap()
}
struct LiveBefore(bool);
impl Drop for LiveBefore {
    fn drop(&mut self) {
        LEXICAL_INSERT_BEFORE.set(self.0);
    }
}
fn live_before(before: bool) -> LiveBefore {
    LiveBefore(LEXICAL_INSERT_BEFORE.replace(before))
}
fn live_full_result(
    program: &ResolvedProgram,
    function: &ResolvedFunction,
    before: bool,
) -> Result<(), Diagnostic> {
    let _before = live_before(before);
    crate::cleanup_plan::replay::validate_structure(program, function)
}
fn live_full_probe(
    program: &ResolvedProgram,
    function: &ResolvedFunction,
    before: bool,
    limit: usize,
) -> (bool, usize, usize, usize, bool) {
    let expected = live_full_result(program, function, true);
    let ((out, allocation), refused, debit, first) = with_limit_usage_refusal(limit, || {
        measure(|| {
            let _before = live_before(before);
            let mut budget = ReplayBudget::new();
            assert!(!budget.selected() && budget.pays_allocations());
            let result = crate::cleanup_plan::replay::validate_structure_with_budget(
                program,
                function,
                &mut budget,
                None,
            );
            if limit == usize::MAX {
                assert_eq!(
                    result, expected,
                    "complete ordinary lexical verdict/Diagnostic"
                );
            }
            let out = (result.is_ok(), MAX_REPLAY_WORK_UNITS - budget.remaining);
            drop(result);
            drop(budget);
            out
        })
    });
    assert!(!allocation.invalid && allocation.live == 0);
    assert_eq!(allocation.allocated, allocation.freed);
    assert_eq!(refused, first.is_some());
    if limit == usize::MAX && out.0 {
        assert!(
            allocation.allocated <= debit,
            "whole successful caller actual allocations must be funded"
        );
    }
    (out.0, out.1, allocation.allocated, debit, refused)
}
