#[test]
fn live_lexical_directories_actual_late_hostiles_keep_all_diagnostic_fields() {
    let p = live_lexical_program(8);
    let i = p
        .functions
        .iter()
        .position(|f| f.cleanup_plan.lexical_control.is_some())
        .unwrap();
    for attack in 0..7 {
        let mut hostile = p.clone();
        let f = &mut hostile.functions[i];
        let mut changed = false;
        match attack {
            0 => {
                f.cleanup_plan.lexical_control.as_mut().unwrap().schema = "foreign";
                changed = true;
            }
            1 => {
                f.cleanup_plan.exits[0].id = crate::cleanup_plan::ExitTargetId(u32::MAX);
                changed = true;
            }
            2 => {
                for exit in &mut f.cleanup_plan.exits {
                    if let ExitContinuation::FunctionReturn {
                        source: CleanupResultSource::Scalar { expression },
                        ..
                    } = &mut exit.continuation
                    {
                        *expression = ExpressionId::from_owned("foreign.return".into());
                        changed = true;
                        break;
                    }
                }
            }
            3..=5 => {
                for block in &mut f.cleanup_plan.blocks {
                    if let Some(at) = block
                        .transitions
                        .iter()
                        .position(|x| matches!(x, CleanupTransition::CallCommit { .. }))
                    {
                        match attack {
                            3 => {
                                block.transitions.remove(at);
                            }
                            4 => {
                                let duplicate = block.transitions[at].clone();
                                block.transitions.insert(at, duplicate);
                            }
                            _ => {
                                if let CleanupTransition::CallCommit { call, .. } =
                                    &mut block.transitions[at]
                                {
                                    *call = ExpressionId::from_owned("foreign.call".into());
                                }
                            }
                        }
                        changed = true;
                        break;
                    }
                }
            }
            _ => {
                f.cleanup_plan.blocks[0].id = BlockId(u32::MAX);
                changed = true;
            }
        }
        assert!(changed, "authored fixture must reach attack {attack}");
        let f = &hostile.functions[i];
        let old = live_full_result(&hostile, f, true);
        let new = live_full_result(&hostile, f, false);
        assert!(old.is_err(), "attack {attack}");
        assert_eq!(new, old, "all six Diagnostic fields attack {attack}");
        let a = live_full_probe(&hostile, f, true, usize::MAX);
        let b = live_full_probe(&hostile, f, false, usize::MAX);
        assert!(!a.0 && !b.0 && !a.4 && !b.4);
    }
}
