fn live_lexical_selector_none_constructor_tax_and_first_gate_remain_exact() {
    let p = program();
    let f = &p.functions[0];
    assert!(f.cleanup_plan.lexical_control.is_none());
    let run = |current: bool, limit| {
        with_limit_usage_refusal(limit, || {
            measure(|| {
                let mut budget = ReplayBudget::new();
                let result = if current {
                    Directory::<u32>::new_with_lexical_insert_selector(
                        f,
                        &mut budget,
                        "live selector",
                    )
                } else {
                    Directory::<u32>::new(f, &mut budget, "live selector")
                };
                let success = result.is_ok();
                let work = MAX_REPLAY_WORK_UNITS - budget.remaining;
                drop(result);
                drop(budget);
                (success, work)
            })
        })
    };
    let old = run(false, usize::MAX);
    let new = run(true, usize::MAX);
    assert!(old.0 .0 .0 && new.0 .0 .0);
    assert!(!old.1 && !new.1);
    assert_eq!(old.0 .1.allocated, new.0 .1.allocated);
    assert_eq!(
        new.2 - old.2,
        super::directory::LEXICAL_INSERT_SELECTOR_BYTES
    );
    assert_eq!(new.0 .0 .1 - old.0 .0 .1, 1);
    assert_eq!(
        super::directory::LEXICAL_INSERT_SELECTOR_BYTES,
        2 * std::mem::size_of::<&Option<Box<crate::cleanup_plan::LexicalControlPlan>>>()
            + 3 * std::mem::size_of::<bool>()
    );
    if std::mem::size_of::<usize>() == 8 {
        assert_eq!(super::directory::LEXICAL_INSERT_SELECTOR_BYTES, 19);
    }
    for current in [false, true] {
        let full = run(current, usize::MAX);
        let exact = run(current, full.2);
        assert!(exact.0 .0 .0 && !exact.1);
        let zero = run(current, 0);
        assert!(!zero.0 .0 .0 && zero.1);
        let bad = run(current, full.2 - 1);
        assert!(!bad.0 .0 .0 && bad.1);
        let positive = super::directory::LEXICAL_INSERT_CONSTRUCTOR_BASE_BYTES
            + if current {
                super::directory::LEXICAL_INSERT_SELECTOR_BYTES
            } else {
                0
            };
        assert_eq!(bad.3.unwrap().requested, positive);
        assert_eq!(bad.2, full.2 - positive);
    }
    // Work is an explicit finite input, never granted or reset after a call.
    let work_probe = |current, work| {
        with_limit_usage_refusal(usize::MAX, || {
            let mut budget = ReplayBudget {
                remaining: work,
                ..ReplayBudget::new()
            };
            let _ = crate::cleanup_plan::replay::take_replay_work_refusal();
            let result = if current {
                Directory::<u32>::new_with_lexical_insert_selector(f, &mut budget, "live selector")
            } else {
                Directory::<u32>::new(f, &mut budget, "live selector")
            };
            let success = result.is_ok();
            let first = result.err();
            let remaining = budget.remaining;
            let refusal = crate::cleanup_plan::replay::take_replay_work_refusal()
                .map(|r| (r.requested, r.remaining));
            let retry = if success {
                None
            } else if current {
                Directory::<u32>::new_with_lexical_insert_selector(f, &mut budget, "live selector")
                    .err()
            } else {
                Directory::<u32>::new(f, &mut budget, "live selector").err()
            };
            (success, first, remaining, retry, refusal)
        })
        .0
    };
    assert_eq!(work_probe(false, 1), (true, None, 0, None, None));
    assert_eq!(work_probe(true, 2), (true, None, 0, None, None));
    let old_short = work_probe(false, 0);
    assert!(!old_short.0 && old_short.2 == 0);
    assert_eq!(old_short.4, Some((1, 0)));
    for work in [0, 1] {
        let new_short = work_probe(true, work);
        assert!(!new_short.0 && new_short.2 == 0);
        assert_eq!(new_short.4, Some((2, work)));
        assert_eq!(
            new_short.1, old_short.1,
            "all original first-work Diagnostic fields"
        );
        assert_eq!(
            new_short.3, old_short.3,
            "all original sticky-work Diagnostic fields"
        );
    }
}
