            let first =
                Directory::<u32>::new_with_lexical_insert_selector(f, &mut budget, "live selector");
            clear_active_floor();
            assert!(first.is_err());
            let retry =
                Directory::<u32>::new_with_lexical_insert_selector(f, &mut budget, "live selector");
            assert!(retry.is_err());
            assert_eq!(budget.remaining, 0);
            drop(retry);
            drop(first);
            drop(budget);
        })
    });
    assert!(!allocation.invalid && allocation.live == 0);
    assert_eq!(allocation.allocated, allocation.freed);
