    let stale = crate::cleanup_plan::replay::allocation::OracleScope::open(1 << 20)
        .unwrap()
        .lease();
    let (raw, refused, debit, first) = with_limit_usage_refusal(1 << 24, || {
        let mut old = ReplayBudget::with_skeleton_limit_oracle(MAX_REPLAY_WORK_UNITS, stale);
        let mut new = ReplayBudget::with_skeleton_limit_oracle(MAX_REPLAY_WORK_UNITS, stale);
        let a = Directory::<u32>::new(f, &mut old, "live selector")
            .err()
            .unwrap();
        let b = Directory::<u32>::new_with_lexical_insert_selector(f, &mut new, "live selector")
            .err()
            .unwrap();
        assert_eq!(a, b);
        (a, b)
    });
    assert!(!refused && debit == 0 && first.is_none());
    drop(raw);
    let ((panicked, allocation), refused, _, _) = with_limit_usage_refusal(1 << 24, || {
        measure(|| {
            std::panic::catch_unwind(std::panic::AssertUnwindSafe(|| {
                let mut budget = ReplayBudget::new();
