                std::panic::resume_unwind(Box::new("intentional complete live directory unwind"));
            }))
            .is_err()
        })
    });
    assert!(panicked && !refused && !allocation.invalid && allocation.live == 0);
    assert_eq!(allocation.allocated, allocation.freed);
}
