pub(super) fn compiled_entry(
    source: &str,
    current_sha: &str,
    current: &str,
    compiled: &str,
) -> String {
    assert_eq!(
        current, compiled,
        "actual complete compiled constructor ENTRY"
    );
    if source == "src/workspace_graph/diagnostics.rs" {
        super::main_e177_final_inputs::value_direct(source, current_sha, current)
