pub(super) fn reviewed(source: &str, current: &str) -> String {
    let expected = match source {
        "src/workspace_graph/identity_resolution/tests.rs" => {
            Some("0798bf2114db010efbfa38538376fbcd849e3287c37bf377aec17aff43362ee4")
        }
