    };
    if let Some(expected) = expected {
        let previous = super::main_e177_final_inputs::value_direct(source, expected, current);
        assert_eq!(
            super::source_sha(&previous),
            expected,
            "complete reviewed identity tests input"
        );
        return previous;
    }
    current.to_owned()
}

